    words: [["일찍", "erta", "early", "рано"], ["일어나다", "turmoq (uyqudan)", "to get up", "вставать"], ["힘들다", "qiyin, og'ir", "hard, tiring", "тяжело"], ["가끔", "ba'zan", "sometimes", "иногда"]],
