    words: [["대회", "musobaqa", "competition, tournament", "соревнование"], ["참가 신청", "ishtirok uchun ariza", "entry application", "заявка на участие"], ["알려 주다", "ma'lum qilmoq", "to let someone know", "сообщать"], ["운동장", "sport maydoni", "sports ground", "спортплощадка"]],
